#!/usr/bin/env python3
"""RC4 PLAYTEST ONLY: require real generated bytes, not artistic approval."""
import hashlib,json,sys
from pathlib import Path
from PIL import Image
ROOT=Path(__file__).resolve().parents[1]; A=ROOT/'assets/images'
def verify(p,sz=None):
 if not p.is_file():raise RuntimeError('Missing '+str(p))
 with Image.open(p) as im:
  if im.format!='PNG' or (sz is not None and im.size!=sz):
   raise RuntimeError('Wrong PNG '+str(p))
  im.verify()
 return hashlib.sha256(p.read_bytes()).hexdigest()
def run():
 report={}
 verify(A/'title_cars_fixed_091.png')
 verify(A/'twc_title_mark_clean.png')
 for z in range(3):
  for n in range(9):verify(A/f'interiors_parallax/school/z{z}_panel_{n}.png',(880,278))
 report['school']=27
 manifest=json.loads((ROOT/'qa/interiors_twc_lab/DANCE_PANEL_GENERATION.json').read_text())['panels']
 if len(manifest)!=9:raise RuntimeError('9 dance manifests required')
 for z in range(3):
  for n in range(3):
   digest=verify(A/f'interiors_parallax/dance/z{z}_panel_{n}.png',(880,286))
   if not any(x.get('zone')==z and x.get('variant')==n and x.get('sha256')==digest for x in manifest):
    raise RuntimeError('Stale dance panel '+str((z,n)))
 report['regenerated_dance_sha256']=9
 football=A/'chapter45/football_parallax'
 fm=json.loads((football/'MANIFEST.json').read_text())
 if set(fm['near']['source_sequence'])!={'football_arrival','football_stands','football_drills'}:
  raise RuntimeError('Football source mix stale')
 for n,sha in fm['source_sha256'].items():
  if verify(A/f'chapter45/{n}.png')!=sha:raise RuntimeError('Football source altered '+n)
 for i in range(6):verify(football/f'near_world_tiles/near_{i}.png',(1100,386))
 report['regenerated_football']=6
 cells={'robot':(144,192),'supporter':(144,192),'tourist':(144,192),
        'navarre_king':(168,216),'estafeta_bull':(270,192),
        'sanfermin_runner':(156,210)}
 report['temporary_enemy_atlases']={}
 for k,(w,h) in cells.items():
  report['temporary_enemy_atlases'][k]=verify(A/f'enemies_new/{k}_atlas.png',(w*4,h*6))
 for k,num in {'breakdancer':6,'bully':5,'referee':6,'rival':6}.items():
  for i in range(num):verify(A/f'enemies/{k}_{i}.png')
 code=(ROOT/'lib/main.dart').read_text()
 if 'TWC_GAMEPLAY_PLAYTEST' not in code or 'isEnemyPlayableInBuild' not in code:
  raise RuntimeError('Playtest enemies not enabled')
 for k in ('cleaning_robot','rival_supporter','tipsy_tourist',
           'navarre_king','estafeta_bull','sanfermin_runner'):
  if "'"+k+"': false" not in code:raise RuntimeError('Art signoff changed: '+k)
 if '0.9.1-rc.4+35' not in (ROOT/'pubspec.yaml').read_text():
  raise RuntimeError('Version mismatch')
 report['artistic_approval']='PENDING - GAMEPLAY TEST ONLY'
 dest=ROOT/'qa/PLAYTEST_RC4_ASSETS.json';dest.write_text(json.dumps(report,indent=2))
 print('RC4 playtest resource gate PASSED. NO aesthetic approval.')
if __name__=='__main__':
 try:run()
 except Exception as e:print('PREVIEW BLOCKED:',str(e),file=sys.stderr);sys.exit(2)
